 setstate(state(4));page.locator('#activity-answer').fill('Innovation');assert page.locator('[data-action="activity-respond:text"]').is_enabled();assert page.locator('.activity-counter').inner_text()=='10 / 40';page.locator('[data-action="activity-respond:text"]').click();assert page.evaluate('sent[1].b.value')=='Innovation'
 setstate(state(5));assert page.locator('textarea#activity-answer').is_visible();page.locator('#activity-answer').fill('My question?');page.locator('[data-action="activity-respond:text"]').click();assert page.evaluate('sent[2].b.value')=='My question?'
 setstate(state(4));page.wait_for_timeout(100);assert page.locator('.participant-screen').evaluate("e=>getComputedStyle(e).getPropertyValue('--answer-bg').trim()") not in ['', '#1f2430'];assert not errors,errors
 # Verify the same renderer inside a phone-sized preview and test the controller's actual result selector and dialog.
 page.set_viewport_size({'width':310,'height':554});setstate(state(1));page.evaluate("()=>{document.body.className='';document.querySelector('#app').className='phone-frame'}");assert page.locator('.phone-brand').bounding_box()['y']+page.locator('.phone-brand').bounding_box()['height']<=page.locator('.phone-content').bounding_box()['y']+1
 control=browser.new_page(viewport={'width':1366,'height':768});control.on('pageerror',lambda e:errors.append(str(e)));control.set_content(html);control.evaluate(boot,dict(src=source,path='/control'))
 cs=state(9);cs['slides']=[*slides,dict(id='comp-b',type='competition',title='Competition B'),dict(id='res-b',type='results',title='Results B',resultsSource='comp-b')];cs.update(screens=[9,11],publishedBySlide={},competitions=[dict(id='competition',title='Competition A',rounds=[dict(id='1',name='Alpha')],completed=['1'],results=[dict(id='1',name='Alpha',count=2,average=6)],max=7),dict(id='comp-b',title='Competition B',rounds=[dict(id='1',name='Beta')],completed=['1'],results=[dict(id='1',name='Beta',count=2,average=8)],max=10)])
 control.evaluate('s=>harness.set(s)',cs);control.evaluate('()=>{window.sent=[];harness.setApi(async(n,b)=>{window.sent.push({n,b});return {...harness.get(),revision:harness.get().revision+1,serverTime:Date.now()}})}')
 select=control.locator('[data-result-source="results"]');assert control.locator('[data-action="publishscores:results"]').is_disabled();select.select_option('competition');assert control.locator('[data-action="publishscores:results"]').is_enabled();assert control.locator('[data-result-source="res-b"]').is_disabled();control.locator('[data-action="publishscores:results"]').click();assert control.locator('dialog').get_by_text('Publish Competition A to Results?').is_visible();control.locator('dialog button[value=yes]').click();control.wait_for_timeout(50);assert control.evaluate('sent[0].b.source')=='competition';assert control.evaluate('sent[0].b.resultSlide')=='results';control.locator('[data-action="show-scores"]').click();assert control.locator('[data-key="all-scores"]').get_by_text('Beta',exact=True).is_visible();assert not errors,errors
 editor=browser.new_page(viewport={'width':1366,'height':768});editor.on('pageerror',lambda e:errors.append(str(e)));editor.set_content(html);editor.evaluate(boot,dict(src=source,path='/admin'));cs['slides'][2]['competitionRounds']=[dict(id='1',name='Alpha')];cs['slides'][10]['competitionRounds']=[dict(id='1',name='Beta')];editor.evaluate('s=>harness.set(s)',cs);editor.locator('[data-action="select:2"]').click();editor.locator('[data-action="groups"]').click();assert editor.locator('#group-host').input_value()=='competition';editor.locator('[data-round="0"]').fill('Alpha changed');editor.locator('#group-host').select_option('comp-b');assert editor.locator('[data-round="0"]').input_value()=='Beta';editor.locator('[data-action="addround"]').click();assert editor.locator('[data-round]').count()==2;editor.locator('#group-host').select_option('competition');assert editor.locator('[data-round="0"]').input_value()=='Alpha changed';assert editor.locator('[data-round]').count()==1;editor.locator('[data-action="closegroups"]').first.click();editor.locator('[data-action="select:9"]').click();editor.locator('[data-prop="resultsSource"]').select_option('comp-b');assert editor.evaluate('harness.deck().slides[9].resultsSource')=='comp-b';assert not errors,errors
